### Spiral Memory Calculation (Day 3)
```javascript
function spiralCoordinates(n) {
    if (n === 1) return [0, 0];

    // Find ring number
    let ring = Math.ceil((Math.sqrt(n) - 1) / 2);
    let ringStart = (2 * ring - 1) ** 2 + 1;
    let sideLength = 2 * ring;

    // Find position on ring
    let position = n - ringStart;
    let side = Math.floor(position / sideLength);
    let offset = position % sideLength;

    // Calculate coordinates based on side
    let x = 0, y = 0;
    switch (side) {
        case 0: x = ring; y = -ring + 1 + offset; break;
        case 1: x = ring - 1 - offset; y = ring; break;
        case 2: x = -ring; y = ring - 1 - offset; break;
        case 3: x = -ring + 1 + offset; y = -ring; break;
    }

    return [x, y];
}
```

### Circular List Operations (Day 17)
```javascript
class CircularBuffer {
    constructor() {
        this.buffer = [0];
        this.position = 0;
    }

    insert(value, steps) {
        this.position = (this.position + steps) % this.buffer.length;
        this.buffer.splice(this.position + 1, 0, value);
        this.position++;
        return this.position;
    }

    getValueAfter(target) {
        const index = this.buffer.indexOf(target);
        return this.buffer[(index + 1) % this.buffer.length];
    }
}
```

### Dual Program Communication (Day 18)
```javascript
class DualProgram {
    constructor(programId, instructions) {
        this.id = programId;
        this.instructions = instructions;
        this.registers = new Map();
        this.registers.set('p', programId);
        this.pc = 0;
        this.sendQueue = [];
        this.receiveQueue = [];
        this.sendCount = 0;
        this.waiting = false;
    }

    execute(otherProgram) {
        this.waiting = false;

        while (this.pc >= 0 && this.pc < this.instructions.length && \!this.waiting) {
            const instruction = this.instructions[this.pc];
            const [cmd, x, y] = instruction.split(' ');

            switch (cmd) {
                case 'snd':
                    const value = this.getValue(x);
                    otherProgram.receiveQueue.push(value);
                    this.sendCount++;
                    this.pc++;
                    break;

                case 'rcv':
                    if (this.receiveQueue.length > 0) {
                        this.registers.set(x, this.receiveQueue.shift());
                        this.pc++;
                    } else {
                        this.waiting = true;
                    }
                    break;

                // Other instructions...
            }
        }

        return \!this.waiting;
    }
}
```

### Tree Structure Analysis (Day 7)
