function buildTree(input) {
    const nodes = new Map();
    const children = new Map();

    // Parse input and build tree structure
    for (const line of input) {
        const [name, weight, childList] = parseLine(line);
        nodes.set(name, weight);
        if (childList) {
            children.set(name, childList);
        }
    }

    // Find root (node with no parent)
    const allChildren = new Set();
    for (const childList of children.values()) {
        childList.forEach(child => allChildren.add(child));
    }

    const root = Array.from(nodes.keys()).find(node => \!allChildren.has(node));

    return { nodes, children, root };
}

function findUnbalanced(tree) {
    function getWeight(node) {
        const nodeWeight = tree.nodes.get(node);
        const childWeights = (tree.children.get(node) || [])
            .map(child => getWeight(child));

        return nodeWeight + childWeights.reduce((sum, w) => sum + w, 0);
    }

    // Find unbalanced node and calculate correction
